-- Drops the entire learning-path layer. Progress/mastery data is derived
-- (recomputable from exercise_attempts once the tables exist again) and
-- the curriculum itself is regenerated by a seed script — nothing here is
-- a primary source of truth that would be lost forever.
DROP TABLE IF EXISTS skill_mastery;
DROP TABLE IF EXISTS user_stage_completions;
DROP TABLE IF EXISTS user_learning_progress;
DROP TABLE IF EXISTS learning_stages;
DROP TABLE IF EXISTS learning_levels;
DROP TABLE IF EXISTS learning_worlds;

DROP INDEX IF EXISTS exercises_difficulty_score;

ALTER TABLE exercises
  DROP COLUMN IF EXISTS difficulty_score,
  DROP COLUMN IF EXISTS instructional_metadata;
